using System;using System.IO;using System.Windows.Forms;
namespace ScoreModern {
 public static class NativeEditCompatibility {
  static bool configuredReproduceInvalidStates;public static bool ReproduceInvalidStates{get{return NativeScoreBehaviour.Enabled?true:configuredReproduceInvalidStates;}private set{configuredReproduceInvalidStates=value;}}
  static bool configuredOriginalGraceState;public static bool OriginalGraceState{get{return NativeScoreBehaviour.Enabled?true:configuredOriginalGraceState;}private set{configuredOriginalGraceState=value;}}
  static bool configuredOriginalQuarterToneWidths;public static bool OriginalQuarterToneWidths{get{return NativeScoreBehaviour.Enabled||configuredOriginalQuarterToneWidths;}}
  static bool configuredLargeInput;public static bool AllowLargeInput{get{return !NativeScoreBehaviour.Enabled&&configuredLargeInput;}}
  static bool configuredRejectMultiDigitF;public static bool RejectMultiDigitF{get{return !NativeScoreBehaviour.Enabled&&configuredRejectMultiDigitF;}}
  static string Settings{get{return "edit-compatibility";}}
  public static void Load(){NativeArrayDiagnostics.Load();Set(false,false);SetGrace(false,false);SetQuarterToneWidths(false,false);SetLargeInput(false,false);SetRejectMultiDigitF(false,false);try{if(NativeSettings.Exists(Settings)&&NativeSettings.ReadAllText(Settings).Trim()=="original")Set(true,false);if(NativeSettings.Exists("grace-chord"))SetGrace(NativeSettings.ReadAllText("grace-chord").Trim()=="original",false);if(NativeSettings.Exists("quarter-tone-spacing"))SetQuarterToneWidths(NativeSettings.ReadAllText("quarter-tone-spacing").Trim()=="original",false);SetLargeInput(NativeSettings.Read("f2-large-input")=="true",false);SetRejectMultiDigitF(NativeSettings.Read("f2-reject-multiple-f-digits")=="true",false);}catch(IOException){}catch(UnauthorizedAccessException){}}
  public static void SetQuarterToneWidths(bool original,bool save){configuredOriginalQuarterToneWidths=original;if(save)NativeSettings.WriteAllText("quarter-tone-spacing",original?"original":"documented");}
  public static void SetGrace(bool original,bool save){OriginalGraceState=original;if(save)NativeSettings.WriteAllText("grace-chord",original?"original":"deterministic");}
  public static void Set(bool original,bool save){ReproduceInvalidStates=original;if(save)NativeSettings.WriteAllText(Settings,original?"original":"prevent");}
  public static void SetLargeInput(bool enabled,bool save){configuredLargeInput=enabled;if(save)NativeSettings.WriteAllText("f2-large-input",enabled?"true":"false");}
  public static void SetRejectMultiDigitF(bool enabled,bool save){configuredRejectMultiDigitF=enabled;if(save)NativeSettings.WriteAllText("f2-reject-multiple-f-digits",enabled?"true":"false");}
  public static void AddMenu(ContextMenuStrip menu){NativeArrayDiagnostics.AddMenu(menu);var item=new ToolStripMenuItem("Editing: reproduce original invalid states");item.Click+=(s,e)=>Set(!ReproduceInvalidStates,true);menu.Items.Add(item);menu.Opening+=(s,e)=>{item.Checked=ReproduceInvalidStates;item.ToolTipText="Off by default. Reproduces original item-0 editing states and the measured text terminator write into a neighbouring record count. Also reproduces the centred leading-extender write into an earlier item and saves unfinished cancelled lyric records when buffer history is established. Reproduces the retained final parameter word when SCORE grows a packed record during transposition and stem normalization. Further unverified post-cancellation mutations stay blocked. It also preserves original mouse entry text above mark 99 and signed rhythm-number wrapping. Use I and an item number to recover from item 0.";};
   var grace=new ToolStripMenuItem("Grace-chord flips: original input-stage behavior");grace.Click+=(s,e)=>SetGrace(!OriginalGraceState,true);menu.Items.Add(grace);
   menu.Opening+=(s,e)=>{grace.Checked=OriginalGraceState;grace.ToolTipText="Off: deterministic recovered grace-chord calculation. On: preserves the original dependence on the retained F2/beam/slur stage header.";};
   var quarter=new ToolStripMenuItem("Justification: measured DOS quarter-tone spacing");quarter.Click+=(s,e)=>SetQuarterToneWidths(!OriginalQuarterToneWidths,true);menu.Items.Add(quarter);menu.Opening+=(s,e)=>{quarter.Checked=OriginalQuarterToneWidths;quarter.ToolTipText="Off: Tom's Help widths for accidentals 106–109. On: the adjacent descriptor values measured in the reference DOS load; different DOS load addresses can change these values.";};
   var large=new ToolStripMenuItem("Editing: allow more than 150 F2 note positions");large.Click+=(s,e)=>SetLargeInput(!AllowLargeInput,true);menu.Items.Add(large);menu.Opening+=(s,e)=>{large.Checked=AllowLargeInput;large.ToolTipText="Use larger Windows input buffers. DOS SCORE can damage its working records above 150 pitched notes.";};
   var fingers=new ToolStripMenuItem("Editing: reject multi-digit F marks");fingers.Click+=(s,e)=>SetRejectMultiDigitF(!RejectMultiDigitF,true);menu.Items.Add(fingers);menu.Opening+=(s,e)=>{fingers.Checked=RejectMultiDigitF;fingers.ToolTipText="Off follows SCORE: F20 10 means F2 applied to targets 0 and 10. On requires a single F digit before the separated targets.";};
  }
 }
}
